<script setup lang="ts">
import {  inject, onMounted , onUnmounted, reactive } from 'vue';
import BackendService from '@/services';
import { type SelectBaseOption, UIButton, UIAlert , UIModal , UITextSmMedium , UICheckbox, UISpin } from '@/ui';




const emit = defineEmits(['switch-tab'])

const localState = reactive({
    loading : true, 
    hasCron : false,
    hasCheckedCronTerms : false, 
    isClearingCron : false, 
    startedClearingCronsAt : null 
});

var cronCleaningInterval = null;


function onMountTasks () {
    localState.loading = true;
    BackendService.Cron.getCronJobs().then((response) => {
        if(response.is_allowed){
          localState.hasCron = response.has_cron > 0 ? true : false;
        }
    });
}

async function clearCron () {
    localState.isClearingCron = true;
    localState.startedClearingCronsAt = new Date();

    await BackendService.Cron.clearCronJobs();
    // const cronJobsResponse = await BackendService.Cron.getCronJobs();
    // localState.hasCron = cronJobsResponse.has_cron > 0 ? true : false;
    // localState.isClearingCron = false;

    startCronCleaningInterval();

}

function startCronCleaningInterval () {
  cronCleaningInterval = setInterval(async () => {
    const timeElapsed = new Date().getTime() - localState.startedClearingCronsAt.getTime();
    const minutesElapsed = Math.floor(timeElapsed / (1000 * 60));
    if (minutesElapsed < 1 ) {
      return;
    }

    if(minutesElapsed > 3) {
      localState.isClearingCron = false;
      clearInterval(cronCleaningInterval);
      return;
    }

    const cronJobsResponse = await BackendService.Cron.getCronJobs();
    localState.hasCron = cronJobsResponse.has_cron > 0 ? true : false;

    if(cronJobsResponse.maintenance_mode === true)
      return ;
    

    if(localState.hasCron === false) {
      localState.isClearingCron = false;
      clearInterval(cronCleaningInterval);
      return;
    }

  }, 1000 * 30 );
}

onMounted(async () => {
  onMountTasks();
});

onUnmounted(() => {
  if (cronCleaningInterval) {
    clearInterval(cronCleaningInterval);
  }
  localState.isClearingCron = false;
})

const lcConnectionMethod = inject('lcConnectionMethod');

</script>
<template>


    <div class="flex justify-between items-center">
        <div>
            <h2 class="text-xl font-sans font-medium mb-1"> Dashboard  </h2>
            <span class="text"> Optimize customer engagement and streamline your marketing efforts </span>
        </div>
    </div>

    <div v-if="localState.hasCron" class="pt-5" >
      <UIAlert id="cron-alert" type="warning" :closable="true" @close="handleClick">
        <template #title> <UITextSmMedium> Action Required </UITextSmMedium>  </template>
        <template #content> 
          We noticed that you have stale cron jobs scheduled on your site which can be cleaned up for improved website performance 
          
          <br />
          <br />

          Please make sure you have done the following steps before taking the action -
          <br />
          <br />


          <ui>
            <li> 
               I have taken a backup for my existing website
            </li>
            <li> 
               All my WordPress cron jobs will get cleared, generally all other non-stale cron jobs will get recreated back automatically after clean up
            </li>
            <li> 
               Your WordPress website might go into maintenance mode for 1-2 minutes 
            </li>
          </ui>

          <br />

          <UICheckbox
            v-model:checked="localState.hasCheckedCronTerms"
            :id="cron-clear-checkbox"
            :checked="localState.hasCheckedCronTerms"
          >
            I have read through the list and have taken a backup of my current website
          </UICheckbox>
        </template>
        <template #actions>
          <div class="flex gap-2">
            <UIButton id="btn-clear-cron" @click="clearCron()" :disabled="!localState.hasCheckedCronTerms" :loading="localState.isClearingCron"  > Clear Now </UIButton>
          </div>
        </template>
      </UIAlert>
    </div>

    <UIModal
      :show="localState.isClearingCron"
    >
      <template #header>
        <div>
          <div class="flex justify-between">
            <span > Clean up in Progress ..</span> 
            <UISpin :size="small" :show="true" />
          </div>
          <p> We are currently cleaning all your stale cron jobs. It would take a few minutes </p>

        </div>
      </template>
    </UIModal>

    <div class="pt-5 flex ">
      <div class=" bg-white shadow-sm border-gray-100 border-solid border-2  flex flex-col items-center w-1/2 p-5 rounded-md	mr-2">
        <div class="text-center" >
          <h3 class="text-lg font-sans font-medium mb-2 mt-0"> Chat Widget </h3>
          <span class="text"> Pull and save chat widgets on your website </span>
        </div>
